uniform float amzp_quality;
uniform float amzp_sharpenAmp;
uniform float amzp_sharpenWidth;
uniform float amzp_edgeThresh;
uniform float amzp_smallDetailSize;
uniform float amzp_scaleTinyDetails;
uniform float amzp_scaleSmallDetails;
uniform float amzp_scaleMediumDetails;
uniform float amzp_scaleLargeDetails;
