uniform float amzp_sharpenChroma;
uniform float amzp_sharpenRed;
uniform float amzp_sharpenGreen;
uniform float amzp_sharpenBlue;
uniform float amzp_maskUse;
uniform float amzp_blurMask;
uniform float amzp_invertMask;
uniform float amzp_alpha;










































    float3 rgb2yuv(float3 c) {
        float y =  0.2126*c.r + 0.7152*c.g + 0.0722*c.b;
        float u = -0.1146*c.r - 0.3854*c.g + 0.5000*c.b;
        float v =  0.5000*c.r - 0.4542*c.g - 0.0458*c.b;
        return float3(y, u, v);
    }

    float3 yuv2rgb(float3 yuv) {
        float r = yuv.x                + 1.5748*yuv.z;
        float g = yuv.x - 0.1873*yuv.y - 0.4681*yuv.z;
        float b = yuv.x + 1.8556*yuv.y;
        return clamp(float3(r, g, b), 0.0, 1.0);
    }



    float2 pixSize() {
        return float2(1.0) / layer;
    }

    float4 samp(float2 uv) {
        return amzTexture(0, clamp(uv, 0.0, 1.0));
    }














    float4 blurGaussian(float2 uv, float2 radius) {
        float4 col = float4(0.0);


        float w0 = 0.44198, w1 = 0.27901;
        float2  r  = radius;


        col += samp(uv + float2(-r.x, -r.y)) * w1*w1;
        col += samp(uv + float2( 0.0, -r.y)) * w0*w1;
        col += samp(uv + float2( r.x, -r.y)) * w1*w1;
        col += samp(uv + float2(-r.x,  0.0)) * w1*w0;
        col += samp(uv + float2( 0.0,  0.0)) * w0*w0;
        col += samp(uv + float2( r.x,  0.0)) * w1*w0;
        col += samp(uv + float2(-r.x,  r.y)) * w1*w1;
        col += samp(uv + float2( 0.0,  r.y)) * w0*w1;
        col += samp(uv + float2( r.x,  r.y)) * w1*w1;
        return col;
    }



    float4 blurGaussian5(float2 uv, float2 r) {
        float4 col = float4(0.0);
        col += samp(uv+float2(-2.*r.x,-2.*r.y))*0.00390625;
        col += samp(uv+float2(-1.*r.x,-2.*r.y))*0.015625;
        col += samp(uv+float2(    0.0,-2.*r.y))*0.0234375;
        col += samp(uv+float2( 1.*r.x,-2.*r.y))*0.015625;
        col += samp(uv+float2( 2.*r.x,-2.*r.y))*0.00390625;
        col += samp(uv+float2(-2.*r.x,-1.*r.y))*0.015625;
        col += samp(uv+float2(-1.*r.x,-1.*r.y))*0.0625;
        col += samp(uv+float2(    0.0,-1.*r.y))*0.09375;
        col += samp(uv+float2( 1.*r.x,-1.*r.y))*0.0625;
        col += samp(uv+float2( 2.*r.x,-1.*r.y))*0.015625;
        col += samp(uv+float2(-2.*r.x,    0.0))*0.0234375;
        col += samp(uv+float2(-1.*r.x,    0.0))*0.09375;
        col += samp(uv+float2(    0.0,    0.0))*0.140625;
        col += samp(uv+float2( 1.*r.x,    0.0))*0.09375;
        col += samp(uv+float2( 2.*r.x,    0.0))*0.0234375;
        col += samp(uv+float2(-2.*r.x, 1.*r.y))*0.015625;
        col += samp(uv+float2(-1.*r.x, 1.*r.y))*0.0625;
        col += samp(uv+float2(    0.0, 1.*r.y))*0.09375;
        col += samp(uv+float2( 1.*r.x, 1.*r.y))*0.0625;
        col += samp(uv+float2( 2.*r.x, 1.*r.y))*0.015625;
        col += samp(uv+float2(-2.*r.x, 2.*r.y))*0.00390625;
        col += samp(uv+float2(-1.*r.x, 2.*r.y))*0.015625;
        col += samp(uv+float2(    0.0, 2.*r.y))*0.0234375;
        col += samp(uv+float2( 1.*r.x, 2.*r.y))*0.015625;
        col += samp(uv+float2( 2.*r.x, 2.*r.y))*0.00390625;
        return col;
    }


    float4 blurBox(float2 uv, float2 radius) {
        float4 col = float4(0.0);
        float w  = 1.0 / 9.0;
        col += samp(uv + float2(-radius.x, -radius.y)) * w;
        col += samp(uv + float2(      0.0, -radius.y)) * w;
        col += samp(uv + float2( radius.x, -radius.y)) * w;
        col += samp(uv + float2(-radius.x,       0.0)) * w;
        col += samp(uv + float2(      0.0,       0.0)) * w;
        col += samp(uv + float2( radius.x,       0.0)) * w;
        col += samp(uv + float2(-radius.x,  radius.y)) * w;
        col += samp(uv + float2(      0.0,  radius.y)) * w;
        col += samp(uv + float2( radius.x,  radius.y)) * w;
        return col;
    }


    float4 doBlur(float2 uv, float2 radius) {
        if (int(amzp_quality) == 0) {

            float mag = length(radius * layer);
            if (mag > 2.0) {
                return blurGaussian5(uv, radius);
            } else {
                return blurGaussian(uv, radius);
            }
        } else {
            return blurBox(uv, radius);
        }
    }






    float4 bandPass(float2 uv, float2 pxSz, float scaleUV) {
        float2 r1 = pxSz * scaleUV;
        float2 r2 = pxSz * scaleUV * 2.0;
        float4 b1 = doBlur(uv, r1);
        float4 b2 = doBlur(uv, r2);
        return b1 - b2;
    }







    float edgeGrad(float2 uv, float2 pxSz) {
        float tl = dot(samp(uv + float2(-pxSz.x, -pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float tc = dot(samp(uv + float2(     0.0, -pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float tr = dot(samp(uv + float2( pxSz.x, -pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float ml = dot(samp(uv + float2(-pxSz.x,      0.0)).rgb, float3(0.299,0.587,0.114));
        float mr = dot(samp(uv + float2( pxSz.x,      0.0)).rgb, float3(0.299,0.587,0.114));
        float bl = dot(samp(uv + float2(-pxSz.x,  pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float bc = dot(samp(uv + float2(     0.0,  pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float br = dot(samp(uv + float2( pxSz.x,  pxSz.y)).rgb, float3(0.299,0.587,0.114));
        float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
        float gy = -tl - 2.0*tc - tr + bl + 2.0*bc + br;
        return length(float2(gx, gy));
    }


    void amzRender() {
        float2 uv    = amzScreenNorm();
        float2 pxSz  = pixSize();


        float4 srcPx = samp(uv);
        float3 srcRGB = srcPx.rgb;







        float base = max(amzp_smallDetailSize, 0.0001) + amzp_sharpenWidth * 0.05;

        float scTiny   = base * 0.5;
        float scSmall  = base;
        float scMedium = base * 2.0;
        float scLarge  = base * 4.0;


        float3 bandTiny   = bandPass(uv, pxSz, scTiny).rgb;
        float3 bandSmall  = bandPass(uv, pxSz, scSmall).rgb;
        float3 bandMedium = bandPass(uv, pxSz, scMedium).rgb;
        float3 bandLarge  = bandPass(uv, pxSz, scLarge).rgb;




        float grad    = edgeGrad(uv, pxSz);
        float edgeMask = 1.0 - smoothstep(amzp_edgeThresh * 0.5, amzp_edgeThresh, grad);


        float3 sharp = (bandTiny   * amzp_scaleTinyDetails
                    + bandSmall  * amzp_scaleSmallDetails
                    + bandMedium * amzp_scaleMediumDetails
                    + bandLarge  * amzp_scaleLargeDetails)
                   * amzp_sharpenAmp * edgeMask;



        float3 srcYUV   = rgb2yuv(srcRGB);
        float3 sharpYUV = rgb2yuv(sharp);

        float3 outYUV;
        outYUV.x = srcYUV.x + sharpYUV.x * amzp_sharpenLuma;   
        outYUV.y = srcYUV.y + sharpYUV.y * amzp_sharpenChroma;  
        outYUV.z = srcYUV.z + sharpYUV.z * amzp_sharpenChroma;  

        float3 outRGB = yuv2rgb(outYUV);



        float3 sharpRGB = outRGB - srcRGB;  
        sharpRGB *= float3(amzp_sharpenRed, amzp_sharpenGreen, amzp_sharpenBlue);
        outRGB = clamp(srcRGB + sharpRGB, 0.0, 1.0);


        float maskVal = 1.0;
        if (int(amzp_maskUse) == 1) {

            maskVal = dot(srcRGB, float3(0.299, 0.587, 0.114));

            if (amzp_blurMask > 0.001) {
                float bm = amzp_blurMask;
                float ml = dot(samp(uv + float2(-bm,   0.)).rgb, float3(0.299,0.587,0.114));
                float mr = dot(samp(uv + float2( bm,   0.)).rgb, float3(0.299,0.587,0.114));
                float mu = dot(samp(uv + float2(  0., -bm)).rgb, float3(0.299,0.587,0.114));
                float md = dot(samp(uv + float2(  0.,  bm)).rgb, float3(0.299,0.587,0.114));
                maskVal = (maskVal + ml + mr + mu + md) * 0.2;
            }
        } else if (int(amzp_maskUse) == 2) {

            maskVal = srcPx.a;
            if (amzp_blurMask > 0.001) {
                float bm = amzp_blurMask;
                float al = samp(uv + float2(-bm,   0.)).a;
                float ar = samp(uv + float2( bm,   0.)).a;
                float au = samp(uv + float2(  0., -bm)).a;
                float ad = samp(uv + float2(  0.,  bm)).a;
                maskVal = (maskVal + al + ar + au + ad) * 0.2;
            }
        }

        if ((amzp_invertMask>0.5)) maskVal = 1.0 - maskVal;
        maskVal = clamp(maskVal, 0.0, 1.0);


        float3 finalRGB = mix(srcRGB, outRGB, maskVal);

        amzOutput = float4(finalRGB, srcPx.a) * amzp_alpha;
    }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

